4	 * Thrown when a request to create an owner carries an E.164 telephone that already belongs to
5	 * another owner. Carries the offending (E.164) telephone so
6	 * {@link DuplicateTelephoneExceptionHandler} can report it. Checked so it appears in the function's
7	 * {@code throws} clause and is routed as an escalation (a 409 Conflict).
8	 */
9	public class DuplicateTelephoneException extends Exception {
10	
11	    private final String telephone;
12	
13	    public DuplicateTelephoneException(String telephone) {
14	        super("An owner with telephone '" + telephone + "' already exists");
15	        this.telephone = telephone;
16	    }
17	
18	    public String getTelephone() {
19	        return this.telephone;
20	    }
21	}
